create type public.controlled_document_status as enum ('DRAFT','IN_REVIEW','APPROVED','OBSOLETE');
create sequence public.controlled_document_number_sequence start 1;
create or replace function public.next_controlled_document_number() returns text language plpgsql volatile set search_path=public as $$ begin return format('DOC-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.controlled_document_number_sequence')::text,6,'0')); end; $$;
create table public.controlled_documents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,document_number text not null unique default public.next_controlled_document_number(),title text not null check(length(trim(title)) between 5 and 240),category text not null check(length(trim(category)) between 2 and 100),status public.controlled_document_status not null default 'DRAFT',current_version integer not null default 1 check(current_version > 0),owner_id uuid references public.user_profiles(id) on delete set null,created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),approved_at timestamptz,approved_by uuid references public.user_profiles(id) on delete set null,obsolete_at timestamptz
);
create table public.controlled_document_versions(
 id uuid primary key default gen_random_uuid(),document_id uuid not null references public.controlled_documents(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,version integer not null check(version > 0),content text not null check(length(trim(content)) between 10 and 50000),change_summary text not null check(length(trim(change_summary)) between 10 and 10000),created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),submitted_at timestamptz,approved_at timestamptz,approved_by uuid references public.user_profiles(id) on delete set null,unique(document_id,version)
);
create index controlled_documents_org_status_idx on public.controlled_documents(organization_id,status,updated_at desc); create index controlled_document_versions_document_idx on public.controlled_document_versions(document_id,version desc);
create trigger controlled_documents_updated before update on public.controlled_documents for each row execute function public.set_updated_at();
alter table public.controlled_documents enable row level security; alter table public.controlled_document_versions enable row level security;
create policy "governance reads controlled documents" on public.controlled_documents for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create policy "governance reads document versions" on public.controlled_document_versions for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create or replace function public.create_controlled_document(target_organization_id uuid,target_title text,target_category text,target_content text,target_change_summary text)
returns uuid language plpgsql security definer set search_path=public as $$ declare document_id uuid;
begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'DOCUMENT_NOT_AUTHORIZED'; end if; if coalesce(length(trim(target_title)),0) not between 5 and 240 or coalesce(length(trim(target_category)),0) not between 2 and 100 or coalesce(length(trim(target_content)),0) not between 10 and 50000 or coalesce(length(trim(target_change_summary)),0) not between 10 and 10000 then raise exception 'DOCUMENT_INVALID_INPUT'; end if;
insert into public.controlled_documents(organization_id,title,category,owner_id,created_by) values(target_organization_id,trim(target_title),trim(target_category),auth.uid(),auth.uid()) returning id into document_id;
insert into public.controlled_document_versions(document_id,organization_id,version,content,change_summary,created_by) values(document_id,target_organization_id,1,trim(target_content),trim(target_change_summary),auth.uid());
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'CONTROLLED_DOCUMENT_CREATED','controlled_document',document_id,jsonb_build_object('version',1),'WEB'); return document_id; end; $$;
create or replace function public.submit_controlled_document_review(target_document_id uuid)
returns void language plpgsql security definer set search_path=public as $$ declare document public.controlled_documents%rowtype;
begin select * into document from public.controlled_documents where id=target_document_id for update; if document.id is null or not public.has_organization_role(document.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'DOCUMENT_NOT_AUTHORIZED'; end if; if document.status not in('DRAFT','APPROVED') then raise exception 'DOCUMENT_INVALID_STATE'; end if;
update public.controlled_document_versions set submitted_at=clock_timestamp() where document_id=document.id and version=document.current_version; update public.controlled_documents set status='IN_REVIEW' where id=document.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(document.organization_id,auth.uid(),'CONTROLLED_DOCUMENT_SUBMITTED','controlled_document',document.id,jsonb_build_object('version',document.current_version),'WEB'); end; $$;
create or replace function public.approve_controlled_document(target_document_id uuid)
returns void language plpgsql security definer set search_path=public as $$ declare document public.controlled_documents%rowtype; version_record public.controlled_document_versions%rowtype;
begin select * into document from public.controlled_documents where id=target_document_id for update; select * into version_record from public.controlled_document_versions where document_id=target_document_id and version=document.current_version for update; if document.id is null or not public.has_organization_role(document.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'DOCUMENT_NOT_AUTHORIZED'; end if; if document.status<>'IN_REVIEW' or version_record.submitted_at is null then raise exception 'DOCUMENT_NOT_IN_REVIEW'; end if; if version_record.created_by=auth.uid() then raise exception 'DOCUMENT_SELF_APPROVAL_FORBIDDEN'; end if;
update public.controlled_document_versions set approved_at=clock_timestamp(),approved_by=auth.uid() where id=version_record.id; update public.controlled_documents set status='APPROVED',approved_at=clock_timestamp(),approved_by=auth.uid() where id=document.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(document.organization_id,auth.uid(),'CONTROLLED_DOCUMENT_APPROVED','controlled_document',document.id,jsonb_build_object('version',document.current_version),'WEB'); end; $$;
create or replace function public.create_controlled_document_version(target_document_id uuid,target_content text,target_change_summary text)
returns uuid language plpgsql security definer set search_path=public as $$ declare document public.controlled_documents%rowtype; version_id uuid; next_version integer;
begin select * into document from public.controlled_documents where id=target_document_id for update; if document.id is null or not public.has_organization_role(document.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'DOCUMENT_NOT_AUTHORIZED'; end if; if document.status='IN_REVIEW' or document.status='OBSOLETE' then raise exception 'DOCUMENT_INVALID_STATE'; end if; if coalesce(length(trim(target_content)),0) not between 10 and 50000 or coalesce(length(trim(target_change_summary)),0) not between 10 and 10000 then raise exception 'DOCUMENT_INVALID_INPUT'; end if; next_version:=document.current_version+1;
insert into public.controlled_document_versions(document_id,organization_id,version,content,change_summary,created_by) values(document.id,document.organization_id,next_version,trim(target_content),trim(target_change_summary),auth.uid()) returning id into version_id; update public.controlled_documents set current_version=next_version,status='DRAFT',approved_at=null,approved_by=null where id=document.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(document.organization_id,auth.uid(),'CONTROLLED_DOCUMENT_VERSION_CREATED','controlled_document',document.id,jsonb_build_object('version',next_version),'WEB'); return version_id; end; $$;
revoke all on function public.create_controlled_document(uuid,text,text,text,text) from public; revoke all on function public.submit_controlled_document_review(uuid) from public; revoke all on function public.approve_controlled_document(uuid) from public; revoke all on function public.create_controlled_document_version(uuid,text,text) from public;
grant execute on function public.create_controlled_document(uuid,text,text,text,text) to authenticated; grant execute on function public.submit_controlled_document_review(uuid) to authenticated; grant execute on function public.approve_controlled_document(uuid) to authenticated; grant execute on function public.create_controlled_document_version(uuid,text,text) to authenticated;
